steps.text:
/*
	VIOC_perf_stuck.sqf - parche perf_stuck de VIOC (2026-10-20). No es del autor de la mision.
	Amplia perf_cleanup (usa su API: VIOC_PERF_fnc_canDeleteVehicle, VIOC_PERF_PLAYER_UNITS, VIOC_PERF_VEH_DIST y el
	contador VIOC_PERF_VEH_DELETED). Lo lanza init.sqf SOLO en el servidor. Parametro de lobby VIOC_PERF_STUCK (1 = si).

	perf_cleanup ya borra los vehiculos VACIOS que la mision vigila (Server_HandleEmptyVehicle). Esto agrega, cada 60 s,
	los vehiculos militares de la IA (tierra y aire; no civiles, barcos, estaticas ni UAV) que quedan ATASCADOS:
	  - averiados sin poder moverse (canMove false) o sin combustible;
	  - aeronaves en tierra con mas del 50 % de danio (helicopteros caidos o danados);
	  - sin municion, si al verlos por primera vez tenian (someAmmo).
	Las aeronaves en el aire no cuentan: las de poco combustible, municion o salud vuelven solas a un aerodromo propio
	con airfields (VIOC_AF_RTB: aterrizan, se reparan, repostan, rearman y vuelven a su orden); mientras estan en ese
	regreso o en servicio en tierra, esto no las toca.
	Tras VIOC_PSTK_TIME s atascado y sin jugadores cerca ni a la vista:
	  1) con tripulacion IA viva: se baja y sigue a pie con su grupo (leaveVehicle);
	  2) vacio (o con muertos dentro): se borra con las reglas de perf_cleanup (VIOC_PERF_VEHICLES: "Nunca" lo apaga;
	     "fuera de bases" respeta las bases; distancia VIOC_PERF_VEH_DIST; nunca el HQ, VIOC_KEEP, VIOC_AF_parked,
	     los usados por un jugador o su grupo en 30 min ni los de apoyo de un jugador).
	Nunca: vehiculos con jugadores o de un grupo con jugador, comprados por un jugador (Owner), ni los de otros sistemas en
	uso (variables vioc_specops, vioc_merc, vioc_uav, vioc_as_, vioc_grg, vioc_iw_, vioc_fb_, vioc_civ, vioc_so_, vioc_tcl,
	vioc_aa, vioc_at_, vioc_af_scramble, vioc_af_doomed, vioc_fpv; grupos vioc_air_busy, vioc_specops, vioc_af_scramble,
	vioc_aa).
	Consola (LOCAL EXEC en el anfitrion): hint (call VIOC_PSTK_fnc_info);
*/
if (!isServer) exitWith {};
if ((missionNamespace getVariable ["VIOC_PERF_STUCK", 1]) <= 0) exitWith {diag_log "[VIOC perf_stuck] apagado (parametro)"};

VIOC_PSTK_TIME = 300;       // s atascado antes de bajar a la tripulacion o borrar
VIOC_PSTK_SEEN_R = 2500;    // m: no se toca si un jugador lo ve a menos de esto
VIOC_PSTK_AIR_DMG = 0.5;    // danio de una aeronave en tierra para contar como caida
VIOC_PSTK_BUSY = ["vioc_specops", "vioc_merc", "vioc_uav", "vioc_as_", "vioc_grg", "vioc_iw_", "vioc_fb_", "vioc_civ", "vioc_so_",
	"vioc_tcl", "vioc_aa", "vioc_at_", "vioc_af_scramble", "vioc_af_doomed", "vioc_fpv"];
VIOC_PSTK_INFO = [0, 0, 0]; // [vehiculos borrados, tripulaciones bajadas, atascados en la ultima pasada]

//--- [vehiculo] -> true si es un vehiculo militar de la IA que esta limpieza puede tocar
VIOC_PSTK_fnc_mine = {
	params ["_v"];
	private _cfg = configFile >> "CfgVehicles" >> typeOf _v;
	if ((getNumber (_cfg >> "side")) > 2 || {(getNumber (_cfg >> "isUav")) == 1}) exitWith {false};
	if ((_v getVariable ["VIOC_KEEP", false]) || {_v getVariable ["VIOC_AF_parked", false]} || {!isNil {_v getVariable "cti_gc_noremove"}}) exitWith {false};
	if (_v in [(missionNamespace getVariable ["CTI_WEST", objNull]) getVariable ["cti_hq", objNull], (missionNamespace getVariable ["CTI_EAST", objNull]) getVariable ["cti_hq", objNull]]) exitWith {false};
	if (!((_v getVariable ["Owner", ""]) in ["", "0"])) exitWith {false};	//--- comprado por un jugador
	if ((time - (_v getVariable ["VIOC_PERF_pUse", -10000000])) < VIOC_PERF_VEH_KEEP_USED) exitWith {false};
	if (((allVariables _v) findIf {private _n = _x; (VIOC_PSTK_BUSY findIf {(_n find _x) == 0}) >= 0}) >= 0) exitWith {false};
	if (!isNil "VIOC_AF_RTB" && {(VIOC_AF_RTB findIf {(_x isEqualType []) && {(_x select 1) isEqualTo _v}}) >= 0}) exitWith {false};	//--- airfields marca con -1 las que salen
	private _crew = (crew _v) select {alive _x};
	if ((_crew findIf {isPlayer _x || {isPlayer (leader (group _x))}}) >= 0) exitWith {false};
	(_crew findIf {
		private _g = group _x;
		(_g getVariable ["vioc_air_busy", false]) || {_g getVariable ["vioc_specops", false]} || {_g getVariable ["vioc_af_scramble", false]} || {_g getVariable ["vioc_aa", false]}
	}) < 0
};

//--- [vehiculo] -> motivo ("" si no esta atascado)
VIOC_PSTK_fnc_reason = {
	params ["_v"];
	private _air = _v isKindOf "Air";
	if (_air && {!(isTouchingGround _v)} && {((getPosATL _v) select 2) > 3}) exitWith {""};	//--- en el aire: airfields
	if (!canMove _v) exitWith {"averiado"};
	if ((fuel _v) < 0.01) exitWith {"sin combustible"};
	if (_air && {(damage _v) > VIOC_PSTK_AIR_DMG}) exitWith {"aeronave danada en tierra"};
	if ((_v getVariable ["vioc_pstk_armed", false]) && {!someAmmo _v}) exitWith {"sin municion"};
	""
};

//--- [vehiculo, jugadores vivos] -> true si no hay jugadores (ni su grupo) cerca y ninguno lo ve
VIOC_PSTK_fnc_hidden = {
	params ["_v", "_pls"];
	private _dist = missionNamespace getVariable ["VIOC_PERF_VEH_DIST", 1000];
	if ((VIOC_PERF_PLAYER_UNITS findIf {(_x distance _v) < _dist}) >= 0) exitWith {false};
	private _asl = (getPosASL _v) vectorAdd [0, 0, 1.5];
	(_pls findIf {
		private _d = _x distance _v;
		(_d < _dist) || {(_d < VIOC_PSTK_SEEN_R) && {([vehicle _x, "VIEW", _v] checkVisibility [eyePos _x, _asl]) > 0.2}}
	}) < 0
};

//--- [vehiculo, motivo, modo de VIOC_PERF_VEHICLES]: baja a la tripulacion o borra el vehiculo
VIOC_PSTK_fnc_act = {
	params ["_v", "_why", "_mode"];
	private _crew = (crew _v) select {alive _x};
	if (_crew isNotEqualTo []) exitWith {
		{ unassignVehicle _x; moveOut _x } forEach _crew;
		{ (group _x) leaveVehicle _v } forEach _crew;
		VIOC_PSTK_INFO set [1, (VIOC_PSTK_INFO select 1) + 1];
		diag_log format ["[VIOC perf_stuck] %1 (%2): baja la tripulacion (%3)", typeOf _v, _why, count _crew];
	};
	if ([_v, _mode] call VIOC_PERF_fnc_canDeleteVehicle) then {
		{ _v deleteVehicleCrew _x } forEach (crew _v);	//--- muertos que sigan dentro
		diag_log format ["[VIOC perf_stuck] %1 (%2): borrado en %3", typeOf _v, _why, mapGridPosition _v];
		deleteVehicle _v;
		VIOC_PERF_VEH_DELETED = VIOC_PERF_VEH_DELETED + 1;
		VIOC_PSTK_INFO set [0, (VIOC_PSTK_INFO select 0) + 1];
	};
};

VIOC_PSTK_fnc_sweep = {
	private _mode = missionNamespace getVariable ["VIOC_PERF_VEHICLES", 2];
	if (_mode < 1) exitWith {};
	private _pls = allPlayers select {alive _x};
	private _n = 0;
	{
		private _v = _x;
		if (alive _v && {(_v isKindOf "LandVehicle") || {_v isKindOf "Air"}} && {!(_v isKindOf "StaticWeapon")} && {[_v] call VIOC_PSTK_fnc_mine}) then {
			if (isNil {_v getVariable "vioc_pstk_armed"}) then {_v setVariable ["vioc_pstk_armed", someAmmo _v]};
			private _why = [_v] call VIOC_PSTK_fnc_reason;
			if (_why == "") then {_v setVariable ["vioc_pstk_t", nil]} else {
				_n = _n + 1;
				private _t = _v getVariable ["vioc_pstk_t", -1];
				if (_t < 0) then {_v setVariable ["vioc_pstk_t", time]} else {
					if ((time - _t) > VIOC_PSTK_TIME && {[_v, _pls] call VIOC_PSTK_fnc_hidden}) then {[_v, _why, _mode] call VIOC_PSTK_fnc_act};
				};
			};
		};
	} forEach vehicles;
	VIOC_PSTK_INFO set [2, _n];
};

VIOC_PSTK_fnc_info = {
	format ["perf_stuck: %1 borrados, %2 tripulaciones bajadas, %3 atascados ahora (espera %4 s, sin jugadores a %5 m ni a la vista a %6 m)",
		VIOC_PSTK_INFO select 0, VIOC_PSTK_INFO select 1, VIOC_PSTK_INFO select 2, VIOC_PSTK_TIME,
		missionNamespace getVariable ["VIOC_PERF_VEH_DIST", 1000], VIOC_PSTK_SEEN_R]
};

[] spawn {
	waitUntil {sleep 5; !isNil "CTI_Init_Server"};
	if (isNil "VIOC_PERF_fnc_canDeleteVehicle") exitWith {diag_log "[VIOC perf_stuck] sin perf_cleanup: no hace nada"};
	sleep 120;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		call VIOC_PSTK_fnc_sweep;
		sleep 60;
	};
};
diag_log "[VIOC perf_stuck] activo";

class VIOC_PERF_STUCK {
	title = "VIOC rendimiento: Vehiculos de la IA atascados (averiados, sin combustible, sin municion o aeronaves danadas en tierra): la tripulacion baja y el vehiculo se borra lejos de los jugadores";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
